 public string Id=id;public int? FailIndex=failIndex;public Action? MutateOriginal;public int ParentDisposed,WorkerDisposed;public Dictionary<string,PortValue>? ParentPublished;public PortValue? OriginalToken,OriginalInputImage;public readonly List<StepEvent> Steps=[];public readonly List<PortValue> TokenInputs=[],ImageInputs=[],LoopInputs=[],FramePorts=[];public readonly List<bool> ReleasedPrivateFields=[];
